export async function invoices(req, db) {
  const organization = req.user.organizationId
  return db.invoices.findMany({ where: { organizationId: organization } })
}

inputs.src/order.js:
export async function submit(client, order) {
  for (let attempt = 0; attempt < 2; attempt++) {
    try { return await client.post("/orders", order) }
    catch (error) { if (attempt === 1) throw error }
  }
}

